    /** Ponto dentro do contorno continental (ray casting) ou de Ilhabela. */
    fun contains(lon: Double, lat: Double): Boolean =
        pointInRing(OUTLINE, lon, lat) || pointInRing(ILHABELA, lon, lat)

    private fun pointInRing(ring: FloatArray, lon: Double, lat: Double): Boolean {
        var inside = false
        val n = ring.size / 2
        var j = n - 1
        for (i in 0 until n) {
            val xi = ring[2 * i].toDouble(); val yi = ring[2 * i + 1].toDouble()
            val xj = ring[2 * j].toDouble(); val yj = ring[2 * j + 1].toDouble()
            if ((yi > lat) != (yj > lat) && lon < (xj - xi) * (lat - yi) / (yj - yi) + xi) inside = !inside
            j = i
        }
        return inside
    }

